Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub:__Entity__),
      (a)-[:MENTIONS]->(p:Person)
WHERE (toLower(pub.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch') OR toLower(pub.name) CONTAINS 'the verge' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'the verge'))
  AND (toLower(p.name) CONTAINS 'sam bankman-fried' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'sam bankman-fried'))
  AND ((toLower(pub.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch')) AND a.published_on > '2023-10-02'
       OR toLower(pub.name) CONTAINS 'the verge' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'the verge'))
OPTIONAL MATCH (a)-[:MENTIONS]->(ao:Organization)
WHERE toLower(ao.name) CONTAINS 'ftx' OR toLower(ao.name) CONTAINS 'alameda'
   OR any(alias IN coalesce(ao.aliases, []) WHERE toLower(alias) CONTAINS 'ftx' OR toLower(alias) CONTAINS 'alameda')
OPTIONAL MATCH (p)-[r]-(o:Organization)
WHERE toLower(o.name) CONTAINS 'ftx' OR toLower(o.name) CONTAINS 'alameda'
   OR any(alias IN coalesce(o.aliases, []) WHERE toLower(alias) CONTAINS 'ftx' OR toLower(alias) CONTAINS 'alameda')
RETURN a.name AS title, a.published_on AS date, pub.name AS publisher,
       collect(DISTINCT CASE WHEN ao IS NOT NULL THEN {entity: p.name, relationship: 'MENTIONS', related: ao.name} END)
       + collect(DISTINCT CASE WHEN o IS NOT NULL THEN {entity: p.name, relationship: type(r), related: o.name} END) AS connectedFacts
