Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p:Publisher),
      (a)-[:MENTIONS]->(s:Person),
      (a)-[:MENTIONS]->(x:__Entity__)
WHERE (toLower(s.name) CONTAINS 'sam altman' OR any(alias IN coalesce(s.aliases, []) WHERE toLower(alias) CONTAINS 'sam altman'))
  AND any(pub IN ['the age', 'fortune', 'techcrunch'] WHERE toLower(p.name) CONTAINS pub OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS pub))
  AND any(term IN ['generosity', 'impact', 'transparency', 'openai', 'board', 'anthropic', 'co-founder', 'remove'] WHERE toLower(x.name) CONTAINS term OR any(alias IN coalesce(x.aliases, []) WHERE toLower(alias) CONTAINS term))
RETURN DISTINCT a.title AS article, a.name AS article_name, a.published_on AS published_on, p.name AS publisher, x.name AS related_entity
LIMIT 10
